// Scratch core types are generated by run.mjs.
/* eslint-disable effecttsgo/any-unknown-in-error-context */
import assert from "node:assert/strict"
import * as BunCrypto from "@effect/platform-bun/BunCrypto"
import * as BunFileSystem from "@effect/platform-bun/BunFileSystem"
import { ByteSize, Deferred, Effect, Exit, Fiber, FileSystem, Layer, Predicate, Scope } from "effect"
import * as Live from "../../core/dist/LiveVolume.js"
import { runtimeOf } from "../../core/dist/internal/runtime.js"

const bound = ByteSize.kilobytes(64)

const fork = (effect) => Effect.forkChild(Effect.result(effect), { startImmediately: true })

const retained = (bytes) => new TextDecoder().decode(bytes).trimEnd().split("\n").slice(1)
  .map((line) => JSON.parse(line)).filter((node) => Predicate.isTagged(node, "file") && node.links.length === 0)

for (const [decision, persisted] of [["committed", true], ["rejected", false], ["unknown", false], ["unknown", true]]) {
  await Effect.runPromise(Effect.scoped(Effect.gen(function*() {
    const disk = yield* FileSystem.FileSystem
    const file = "cleanup-image"
    yield* disk.writeFile(file, yield* Live.prepareEmptyImage())
    const entered = yield* Deferred.make()
    const release = yield* Deferred.make()
    let closing = false
    let offers = 0

    const commit = (bytes) => Effect.gen(function*() {
      if (closing) {
        offers++
        assert.deepEqual(retained(bytes), [])
        yield* Deferred.succeed(entered, undefined)
        yield* Deferred.await(release)
      }

      if (!closing || persisted) {
        yield* disk.writeFile("cleanup-pending", bytes)
        yield* disk.rename("cleanup-pending", file)
      }

      return closing ? decision : "committed"
    })

    const { volume, shutdown } = yield* Live.openImage(yield* disk.readFile(file), bound, commit)
    const fs = yield* volume.caller()
    const lastScope = yield* Scope.make()
    const first = yield* fs.open("/held", { access: "readWrite", create: "exclusive" })
    const last = yield* fs.open("/held", { access: "readWrite" }).pipe(Scope.provide(lastScope))
    const key = yield* volume.referenceKey(yield* fs.lookup("/held"))
    yield* first.write(Uint8Array.of(9, 7))
    yield* fs.unlink("/held")
    assert.equal((yield* Effect.flip(fs.lookup("/held"))).code, "NotFound")
    assert.deepEqual((yield* last.pread(2, 0n)).bytes, Uint8Array.of(9, 7))
    const held = yield* disk.readFile(file)
    assert.deepEqual(retained(held).map((node) => node.ino), [Number(key.ino)])
    assert.equal((yield* runtimeOf(volume).owner.usage).handles, 2)
    closing = true
    yield* first.close
    assert.equal(offers, 0)
    assert.equal((yield* runtimeOf(volume).owner.usage).handles, 1)

    // Also exercise a scoped last release while a volume observation waits on the decision.
    const scoped = decision === "unknown" && !persisted
    const worker = yield* fork(scoped ? Scope.close(lastScope, Exit.void) : last.close)
    yield* Deferred.await(entered)
    const observation = yield* fork(volume.usage)
    const waiting = observation.pollUnsafe() === undefined
    yield* Deferred.succeed(release, undefined)
    assert.ok(waiting)
    const closed = yield* Fiber.join(worker)
    const usage = yield* Fiber.join(observation)

    if (decision === "committed") {
      assert.equal(closed._tag, "Success")
      assert.deepEqual(usage.success, { entries: 0, usedBytes: 0n })
    } else {
      if (scoped) assert.equal(closed._tag, "Success")
      else assert.equal(closed.failure.code, decision === "unknown" ? "OutcomeUnknown" : "StorageRejected")
      assert.equal(usage.failure.code, "VolumeUnavailable")
      assert.equal((yield* Effect.flip(fs.mkdir("/later"))).code, "VolumeUnavailable")
    }

    // The frozen public volume cannot report whether the underlying resources were released.
    const released = yield* runtimeOf(volume).owner.usage
    assert.deepEqual([released.handles, released.unreachableRetainedObjects, released.contentBytes], [0, 0, 0n])
    yield* Scope.close(lastScope, Exit.void)
    yield* shutdown
    assert.equal(offers, 1)
    const bytes = yield* disk.readFile(file)

    if (persisted) assert.deepEqual(retained(bytes), [])
    else assert.deepEqual(bytes, held)

    closing = false
    const reopened = yield* Live.openImage(bytes, bound, commit)
    const fresh = yield* reopened.volume.caller()
    assert.equal((yield* Effect.flip(fresh.lookup("/held"))).code, "NotFound")
    assert.equal((yield* Effect.flip(reopened.volume.resolveReferenceKey(key))).code, "StaleReference")
    assert.deepEqual(yield* reopened.volume.usage, { entries: 0, usedBytes: 0n })
    yield* fresh.mkdir("/next")
    assert.equal((yield* fresh.stat("/next")).ino, key.ino + 1n)
    yield* reopened.shutdown
  })).pipe(Effect.provide(Layer.merge(BunCrypto.layer, BunFileSystem.layer))))
}

process.stdout.write("Last-handle close passed two-handle, storage-decision and v1 reopen checks.\n")
